using FMODUnity;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EnemySFXData", menuName = "Data/SFX/EnemySFXData")]
public class EnemySFXData : SFXData
{
	[Header("Enemy Attack SFX")]
	[SerializeField]
	private bool enableEnemyAttack;

	[SerializeField]
	[ShowIf("enableEnemyAttack")]
	private EventReference enemyAttack;

	[SerializeField]
	private bool enableEnemyAttackDelay;

	[SerializeField]
	[ShowIf("enableEnemyAttackDelay")]
	private float enemyAttackDelay;

	[SerializeField]
	private bool enableEnemyOverCorruptAttackSkillSFX;

	[SerializeField]
	[ShowIf("enableEnemyOverCorruptAttackSkillSFX")]
	private EventReference enemyOverCorruptAttackSkillSFX;

	[SerializeField]
	[ShowIf("enableEnemyOverCorruptAttackSkillSFX")]
	private bool enableEnemyOverCorruptAttackSkillDelay;

	[SerializeField]
	[ShowIf("enableEnemyOverCorruptAttackSkillDelay")]
	private float enemyOverCorruptAttackSkillDelay;

	[Header("Over Corrupt SFX")]
	[SerializeField]
	private bool enableOverCorrupt;

	[SerializeField]
	[ShowIf("enableOverCorrupt")]
	private EventReference overCorrupt;

	[SerializeField]
	private bool enableCustomOverCorrupt;

	[SerializeField]
	[ShowIf("enableCustomOverCorrupt")]
	private CustomEnemySFXData customEnemySFXData;

	[Header("Start of Battle SFX")]
	[SerializeField]
	private bool enableStartOfBattle;

	[SerializeField]
	[ShowIf("enableStartOfBattle")]
	private EventReference startOfBattle;

	[Header("Purified SFX")]
	[SerializeField]
	private bool enablePurified;

	[SerializeField]
	[ShowIf("enablePurified")]
	private EventReference purified;

	[SerializeField]
	private bool disableGenericPurifiedSFX;

	[Header("Purified Run Away SFX")]
	[SerializeField]
	private bool enablePurifiedRunAway;

	[SerializeField]
	[ShowIf("enablePurifiedRunAway")]
	private EventReference purifiedRunAway;

	[Header("Vanish SFX")]
	[SerializeField]
	private bool enableVanish;

	[SerializeField]
	[ShowIf("enableVanish")]
	private EventReference vanish;

	public bool EnableEnemyAttack => enableEnemyAttack;

	public bool EnableEnemyAttackDelay => enableEnemyAttackDelay;

	public float EnemyAttackDelay => enemyAttackDelay;

	public bool EnableEnemyOverCorruptAttackSkillSFX => enableEnemyOverCorruptAttackSkillSFX;

	public EventReference EnemyOverCorruptAttackSkillSFX => enemyOverCorruptAttackSkillSFX;

	public bool EnableEnemyOverCorruptAttackSkillDelay => enableEnemyOverCorruptAttackSkillDelay;

	public float EnemyOverCorruptAttackSkillDelay => enemyOverCorruptAttackSkillDelay;

	public bool EnableOverCorrupt => enableOverCorrupt;

	public EventReference OverCorrupt => overCorrupt;

	public bool EnableCustomOverCorrupt => enableCustomOverCorrupt;

	public CustomEnemySFXData CustomEnemySFXData => customEnemySFXData;

	public bool EnableStartOfBattle => enableStartOfBattle;

	public EventReference StartOfBattle => startOfBattle;

	public bool EnablePurified => enablePurified;

	public EventReference Purified => purified;

	public bool DisableGenericPurifiedSFX => disableGenericPurifiedSFX;

	public bool EnablePurifiedRunAway => enablePurifiedRunAway;

	public EventReference PurifiedRunAway => purifiedRunAway;

	public bool EnableVanish => enableVanish;

	public EventReference Vanish => vanish;

	[Button(null)]
	public void PlayEnemyAttackSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyAttack);
	}
}
